package online.wydmeal.reservation;
import android.app.*;
import android.content.*;
import android.widget.*;
import org.json.*;
import java.security.SecureRandom;
import java.util.concurrent.*;
import cn.jpush.android.api.JPushInterface;
import cn.jiguang.api.JCoreInterface;
import cn.jiguang.api.JCoreManager;

/** Only opaque wake-ups cross JPush. Message details always require a live login. */
public final class PushBridge {
 private static final ExecutorService IO=Executors.newSingleThreadExecutor();
 private static boolean initialized;private static long lastSync;
 private static SharedPreferences prefs(Context c){return c.getSharedPreferences("instant_push",0);}
 private static String active(Context c){return c.getSharedPreferences("system_notices",0).getString("active","");}
 private static boolean enabled(Context c){return prefs(c).getBoolean("consent",false)&&prefs(c).getBoolean("enabled",true)&&NoticeNotifier.allowed(c)&&!active(c).isEmpty();}
 public static void offer(Activity a){if(active(a).isEmpty())return;SharedPreferences p=prefs(a);if(p.getBoolean("asked",false)){sync(a,false);return;}p.edit().putBoolean("asked",true).apply();new AlertDialog.Builder(a).setTitle("开启即时推送？").setMessage("开启后，极光推送会处理设备标识、网络信息和推送状态，用于及时提醒预约动态。推送内容不包含用餐详情，详情会在验证登录后从本站获取。你可以随时在系统通知设置中关闭。\n\n华为／荣耀厂商通道尚未配置，应用被系统清理后可能延迟；仍保留后台定时检查。").setNeutralButton("隐私说明",(d,w)->{p.edit().putBoolean("asked",false).apply();a.startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://www.jiguang.cn/license/privacy")));}).setNegativeButton("暂不开启",null).setPositiveButton("同意并开启",(d,w)->{p.edit().putBoolean("consent",true).putBoolean("enabled",true).apply();sync(a,true);}).show();}
 private static synchronized void start(Context c){if(initialized)return;JPushInterface.setDebugMode(false);JCoreManager.setLBSEnable(c,false);JCoreInterface.setWakeEnable(c,false);JPushInterface.setGeofenceEnable(c,false);JPushInterface.setSmartPushEnable(c,false);JPushInterface.setDataInsightsEnable(c,false);JPushInterface.init(c);initialized=true;}
 public static void sync(Context context,boolean force){Context c=context.getApplicationContext();if(!enabled(c)){if(initialized)JPushInterface.stopPush(c);return;}start(c);JPushInterface.resumePush(c);String rid=JPushInterface.getRegistrationID(c);if(rid==null||rid.isEmpty())return;long now=System.currentTimeMillis();synchronized(PushBridge.class){if(!force&&now-lastSync<60000)return;lastSync=now;}IO.execute(()->{try{ApiClient api=new ApiClient(c);String session=api.sessionKey(),user=active(c);if(session.isEmpty()||user.isEmpty())return;SharedPreferences p=prefs(c);String proof=proof(c);JSONObject result=api.json("/api/mobile-push",ApiClient.object("registrationId",rid,"deviceProof",proof,"enabled",true));if(enabled(c)&&session.equals(new ApiClient(c).sessionKey())&&user.equals(active(c)))p.edit().putString("binding",result.getString("binding")).putString("session",session).putString("rid",rid).putString("status","设备已绑定，等待推送连接").apply();}catch(Exception e){prefs(c).edit().putString("status","设备暂未绑定，请联网后重新连接").apply();}});}
 private static synchronized String proof(Context c){SharedPreferences p=prefs(c);String proof=p.getString("proof","");if(proof.isEmpty()){byte[] b=new byte[32];new SecureRandom().nextBytes(b);StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format(java.util.Locale.ROOT,"%02x",v&255));proof=s.toString();p.edit().putString("proof",proof).commit();}return proof;}
 public static void inactive(Context context){Context c=context.getApplicationContext();prefs(c).edit().remove("binding").remove("session").apply();lastSync=0;if(initialized)JPushInterface.stopPush(c);}
 public static void disable(Context context){Context c=context.getApplicationContext();String rid=prefs(c).getString("rid","");prefs(c).edit().putBoolean("enabled",false).remove("binding").apply();if(initialized)JPushInterface.stopPush(c);IO.execute(()->{try{if(!rid.isEmpty())new ApiClient(c).json("/api/mobile-push",ApiClient.object("registrationId",rid,"deviceProof",proof(c),"enabled",false));}catch(Exception ignored){}});}
 public static void receive(Context context,String extra,Runnable finish){Context c=context.getApplicationContext();try{JSONObject e=new JSONObject(extra);SharedPreferences p=prefs(c);if(!enabled(c)||!active(c).equals(e.optString("user_id"))||!p.getString("binding","").equals(e.optString("binding"))||e.optString("binding").isEmpty()){finish.run();return;}String binding=e.optString("binding");IO.execute(()->{try{ApiClient api=new ApiClient(c);if(!api.sessionKey().equals(prefs(c).getString("session","")))return;for(int page=0;page<5;page++){if(!enabled(c)||!binding.equals(prefs(c).getString("binding","")))return;String id=active(c);long cursor=c.getSharedPreferences("system_notices",0).getLong("cursor:"+id,0);JSONObject r=api.json("/api/mobile-notices?after="+cursor,null);if(!id.equals(r.optString("userId")))return;NoticeNotifier.deliver(c,id,r.getJSONArray("notices"),r.optLong("nextCursor",cursor));if(!r.optBoolean("hasMore"))break;}}catch(Exception ignored){/* periodic check remains available */}finally{finish.run();}});}catch(Exception ignored){finish.run();}}
 public static void settings(Activity a,LinearLayout parent,NativeUi ui){SharedPreferences p=prefs(a);ui.gap(parent,20);parent.addView(ui.text("即时推送",20,ui.text,true));parent.addView(ui.body(p.getString("status","尚未连接极光推送")));ui.fullButton(parent,p.getBoolean("enabled",true)&&p.getBoolean("consent",false)?"关闭即时推送":"开启即时推送",false,()->{if(p.getBoolean("enabled",true)&&p.getBoolean("consent",false)){disable(a);Toast.makeText(a,"即时推送已关闭",Toast.LENGTH_SHORT).show();}else{p.edit().putBoolean("asked",false).apply();offer(a);}});ui.fullButton(parent,"重新连接推送",false,()->{if(!p.getBoolean("consent",false)||!p.getBoolean("enabled",true)){p.edit().putBoolean("asked",false).apply();offer(a);}else{sync(a,true);Toast.makeText(a,"正在重新绑定设备",Toast.LENGTH_SHORT).show();}});parent.addView(ui.body("华为／荣耀厂商通道待配置。请允许通知，并在手机的应用启动管理中允许后台运行。强行停止应用后需要重新打开。"));String rid=p.getString("rid","");if(!rid.isEmpty()){TextView view=ui.body("设备推送标识："+rid);view.setTextIsSelectable(true);parent.addView(view);}}
 public static void connected(Context c,boolean connected){prefs(c).edit().putString("status",connected?"极光通道已连接":"极光通道正在连接").apply();if(connected)sync(c,false);}
}
